-- =============================================
-- TRUNCATE (clean slate)
-- =============================================
TRUNCATE TABLE edge_time_windows, edges, nodes, carriages, trains RESTART IDENTITY CASCADE;

-- =============================================
-- NODES (50 stations)
-- =============================================

-- =============================================
-- EDGES (200 connections)
-- capacity: 500-2000 (up from 50-500)
-- covers combined train+carriage weight
-- =============================================
-- Edges 1-49: backbone chain (always connected)
-- Edges 50-200: additional random connections

-- =============================================
-- EDGE_TIME_WINDOWS
-- Backbone: full-day window
-- Others: 2-3 overlapping bands covering 24h
-- =============================================

-- =============================================
-- CARRIAGES (30)
-- weight: 8-45t each
-- worst case 30 carriages = ~1350t
-- =============================================

-- =============================================
-- TRAINS (15)
-- capacity: 1000-4000t (up from 500-2000)
-- used_weight: 10-40% of capacity
-- leaves 600-3600t available for carriages
-- =============================================
